begin;
select pg_advisory_xact_lock(hashtext('onboard:gazeta-bragantina'));
do $onboard$
declare cid uuid; pid uuid; aid uuid; tid uuid; payload jsonb := '{"roadmap": {"stack": {"architecture": {"title": "A tecnologia por trás da Gazeta.", "description": "Portal de notícias, Painel da Redação e área do leitor. A versão visual final está em análise; as ativações de produção seguem nas etapas do projeto.", "inputs": [{"id": "portal", "brand": "react", "title": "Portal de notícias", "tool": "Next.js + React", "detail": "Páginas, busca, SEO e redirects do acervo", "href": "https://nextjs.org"}, {"id": "editorial", "brand": "", "title": "Painel da Redação", "tool": "Tiptap", "detail": "Editor rico, capa, revisão e agendamento", "href": "https://tiptap.dev"}, {"id": "readers", "brand": "supabase", "title": "Leitores e redação", "tool": "Supabase Auth", "detail": "Login, perfis e permissões com RLS", "href": "https://supabase.com/auth"}], "core": {"id": "core", "brand": "vercel", "title": "Portal na nuvem", "tool": "Vercel", "detail": "Hospedagem prevista · deploy de produção pendente", "href": "https://vercel.com"}, "services": [{"id": "database", "brand": "supabase", "title": "Acervo e banco de dados", "tool": "Supabase / PostgreSQL", "detail": "Acervo importado, busca e agendamento via pg_cron", "href": "https://supabase.com/database"}, {"id": "media", "brand": "", "title": "Imagens e arquivos", "tool": "Cloudflare R2", "detail": "Código preparado · conta, bucket e migração pendentes", "href": "https://developers.cloudflare.com/r2/"}, {"id": "newsletter", "brand": "", "title": "Newsletter", "tool": "Resend", "detail": "Código pronto · chave e domínio pendentes", "href": "https://resend.com"}, {"id": "push", "brand": "", "title": "Avisos no navegador", "tool": "Web Push / VAPID", "detail": "Código pronto · ativação das chaves pendente", "href": "https://developer.mozilla.org/en-US/docs/Web/API/Push_API"}], "caption": "O protótipo de aprovação usa HTML, CSS e JavaScript. O portal conectado usa Next.js e Supabase; R2, Resend e push ainda dependem de ativação. O percentual das etapas não significa que o portal já esteja em produção."}}, "costs": [], "next_steps": {"presentation": {"phase_mode": "source", "review_label": "Versão final em análise", "review_description": "Aprovação visual em andamento. A publicação do portal depende das ativações e da migração previstas no roadmap.", "prototype_title": "Navegue pela versão final.", "editor_lock_reason": "O Editor está bloqueado porque a versão final está em análise. Navegue pela aba Protótipo e alinhe suas observações com a equipe.", "hero_title": "O novo portal da Gazeta, em análise final.", "hero_description": "Explore a versão de aprovação, conheça a tecnologia do portal e acompanhe as cinco fases do roadmap.", "infrastructure_title": "As propostas e o escopo aprovado.", "scope_options": [{"label": "A · Portal moderno", "selected": false, "features": ["Portal responsivo, editorias e capa organizada por seções.", "Painel básico da redação e 2 modelos: notícia padrão e coluna/opinião.", "Sindicato e jornal de bairro em abas com visual próprio.", "Espaços fixos para anúncios e otimização para Google e Google Notícias.", "Suporte pós-entrega: 30 dias. Prazo estimado na proposta: 4–6 semanas."]}, {"label": "B · Portal + comunidade", "selected": true, "features": ["Toda a base da opção A, com painel editorial completo.", "4 modelos: notícia padrão, coluna/opinião, foto-reportagem e reportagem especial.", "Duas seções com capa, identidade e anúncios próprios, publicadas pela equipe Gazeta em um painel único.", "Cadastro de leitores, área personalizada e newsletter por e-mail.", "Base preparada para assinatura futura e avisos de notícias no navegador.", "Suporte pós-entrega: 60 dias. Prazo estimado na proposta: 7–9 semanas."]}, {"label": "C · Ecossistema completo", "selected": false, "features": ["Tudo da opção B, mais aplicativo instalável no celular (iPhone e Android).", "Sistema completo de anúncios e relatórios de audiência, anúncios e assinantes.", "Todos os modelos de conteúdo, incluindo cobertura ao vivo, vídeo e personalizados.", "Avisos de notícias no navegador e no celular.", "Suporte pós-entrega: 90 dias. Prazo estimado na proposta: 10–12 semanas."]}], "scope_note": "Opção B aprovada. A operação contempla hospedagem, banco de dados, manutenção e suporte a partir da entrega. Aplicativo nativo nas lojas App Store e Google Play é uma etapa futura opcional. Os prazos acima são as estimativas da proposta, não novas datas de entrega.", "hide_project_navigation": true, "started_on": "2026-07-22", "delivery_from": "2026-09-09", "delivery_to": "2026-09-23", "delivery_note": "Prazo combinado: 7–9 semanas desde o início"}, "task_details": {}}, "references": ["Roadmap: painel-controle/index.html", "Stack e estado: README.md, CONTINUAR.md e portal/package.json", "Protótipo: pacote de aprovação de 15/09", "Escopo aprovado: Proposta Maisis / Gazeta Bragantina, junho de 2026, opção B (páginas 3 a 7)."], "tiers": {}, "preferred_tier": null, "prototype_url": "/prototipos/gazeta-bragantina/aprovacao-15-09/COMECE-POR-AQUI.html"}, "tasks": [{"source_id": "f0-1", "title": "Acessos ao ambiente atual (WordPress, DNS, hospedagem, e-mail)", "phase": "Fase 0 · Preparação", "status": "concluido", "note": "Concluído em 18/08/2026 — a Maisis liberou o wp-admin e promoveu o usuário \"redacao\" a administrador. Foi isso que destravou Ferramentas → Exportar, o phpMyAdmin e o download da mídia no mesmo dia.", "week": 1, "position": 0}, {"source_id": "f0-4", "title": "Contrato e entrada", "phase": "Fase 0 · Preparação", "status": "concluido", "note": "Etapa comercial, fora do escopo técnico — nenhuma pendência de engenharia depende dela.", "week": 1, "position": 1}, {"source_id": "f0-5", "title": "Definição de stack — Next.js SSR (Vercel) + Supabase + Cloudflare R2", "phase": "Fase 0 · Preparação", "status": "concluido", "note": "Concluído e documentado na arquitetura de referência do projeto.", "week": 1, "position": 2}, {"source_id": "f1-1", "title": "Estrutura do portal (cabeçalho, rodapé, navegação, grid da capa)", "phase": "Fase 1 · Frontend", "status": "concluido", "note": "Concluído no protótipo estático — aprovado em 28/07.", "week": 1, "position": 3}, {"source_id": "f2-1", "title": "Modelo A — notícia padrão", "phase": "Fase 1 · Frontend", "status": "concluido", "note": "Concluído no protótipo — dateline, barra de compartilhamento, anúncios no corpo, ficha de serviço, nota de correção.", "week": 3, "position": 4}, {"source_id": "f2-2", "title": "Modelo B — coluna / opinião", "phase": "Fase 1 · Frontend", "status": "concluido", "note": "Concluído no protótipo — fundo diferenciado, selo OPINIÃO, capitular.", "week": 3, "position": 5}, {"source_id": "f2-3", "title": "Modelo C — foto-reportagem", "phase": "Fase 1 · Frontend", "status": "concluido", "note": "Concluído no protótipo — abertura full-bleed, mosaico, lightbox com teclado e swipe.", "week": 4, "position": 6}, {"source_id": "f1-2", "title": "Capa por editorias", "phase": "Fase 1 · Frontend", "status": "concluido", "note": "Concluído no protótipo — destaque, grade e paginação real. Só a editoria Política foi montada como exemplo; as demais reaproveitam o mesmo modelo.", "week": 2, "position": 7}, {"source_id": "f2-7", "title": "Espaços de anúncio", "phase": "Fase 1 · Frontend", "status": "concluido", "note": "Concluído no protótipo — billboard, leaderboard, retângulo e meia-página com altura reservada (CLS zero). Falta o sistema real de veiculação.", "week": 5, "position": 8}, {"source_id": "f2-5", "title": "LP especial — Sindicato (cara de site próprio)", "phase": "Fase 1 · Frontend", "status": "concluido", "note": "Concluído no protótipo — tema azul institucional, canto reto. Cores e logotipo ainda são placeholder, a trocar por manual de marca real.", "week": 4, "position": 9}, {"source_id": "f2-4", "title": "Modelo D — especial / longform", "phase": "Fase 1 · Frontend", "status": "concluido", "note": "Concluído no protótipo — capa imersiva, barra de progresso de leitura, sumário sticky.", "week": 4, "position": 10}, {"source_id": "f2-6", "title": "LP especial — Jornal de Bairro (cara de site próprio)", "phase": "Fase 1 · Frontend", "status": "concluido", "note": "Concluído no protótipo — tema verde, sem serifa, cantos arredondados. Mesma ressalva de cor/logo placeholder.", "week": 5, "position": 11}, {"source_id": "f1-3", "title": "Painel editorial conectado (login, rascunho, revisão e publicação)", "phase": "Fase 2 · Migração e Backup", "status": "concluido", "note": "Concluído em 23/09/2026 no portal Next.js local: Auth, equipe com RLS, criação, edição, revisão e publicação de matérias. Primeira conta administradora criada; login e leitura de rascunhos testados. A demo antiga em localhost:5173 continua estática.", "week": 2, "position": 12}, {"source_id": "f2-9", "title": "Organização Supabase Free, banco e tabelas criados", "phase": "Fase 2 · Migração e Backup", "status": "concluido", "note": "Concluído em 23/09/2026 — organização Gazeta Bragantina e projeto Free em São Paulo, schema versionado com 27 tabelas, views e RLS. Banco com cerca de 84 MB de 500 MB após o índice de busca; nenhuma mídia importada.", "week": 3, "position": 13}, {"source_id": "f2-10", "title": "Portal Next.js conectado ao acervo e à busca", "phase": "Fase 2 · Migração e Backup", "status": "concluido", "note": "Concluído em 23/09/2026 no portal local: capa, editorias, matérias e busca leem o Supabase. Verificado por build e respostas HTTP 200. Ainda falta transpor a experiência visual completa do protótipo e publicar em produção.", "week": 5, "position": 14}, {"source_id": "f2-11", "title": "Backend do Painel da Redação (agendamento, mídia e editor rico)", "phase": "Fase 2 · Migração e Backup", "status": "concluido", "note": "Concluído em 23/09/2026: editor rico, gestão de autores/editorias/capa, agendamento automático via pg_cron e fluxo de upload de novas imagens com RLS. Upload permanece desativado até a conta R2 ser configurada; equivalência visual com o protótipo é trabalho de frontend.", "week": 6, "position": 15}, {"source_id": "f0-3", "title": "Auditoria de conteúdo (padrão de URLs, volume de posts, amostra de 50 matérias)", "phase": "Fase 2 · Migração e Backup", "status": "concluido", "note": "Concluído em 18/08/2026 — permalink atual confirmado como /%year%/%monthnum%/%day%/%postname%/ na raiz, sem acento e sem maiúscula. Volume real: 7.577 matérias publicadas, mapeadas em dados-wordpress/mapa-completo-publicados.csv, mais a amostra de 50 (10 antigas + 20 aleatórias + 20 recentes). Risco de HTML sujo bem menor que o esperado: [caption] em 656 e [gallery] em 97 (shortcodes nativos), tabela em 9, iframe em 0, marcação do Word em 1. Falta só o crawl completo de URLs para validar a virada de DNS.", "week": 1, "position": 16}, {"source_id": "f0-2", "title": "Backup total do WordPress (banco de dados + mídia + tema)", "phase": "Fase 2 · Migração e Backup", "status": "concluido", "note": "Concluído em 18/08/2026 — banco exportado pelo phpMyAdmin (143 MB, fora do git por conter hash de senha) e wp-content/uploads baixado inteiro via WP File Manager, ano a ano (8,7 GB, 2019–2026, fora do git). Backup de tema dispensado: o site novo não usa o JNews.", "week": 1, "position": 17}, {"source_id": "f1-5", "title": "Redirects 301 das URLs antigas (preservar SEO)", "phase": "Fase 2 · Migração e Backup", "status": "concluido", "note": "Implementado em 23/09/2026 no Next.js local: 7.609 redirects 301 via mapa estático, sem consulta por requisição. Auditoria confirmou 7.569 destinos de matérias e 40 de editorias válidos; 8 posts sem título apontam para a editoria. Teste local: URL antiga → 301 → 200 em um salto. Falta validar em produção após go-live e revisar as 31 editorias legadas.", "week": 3, "position": 18}, {"source_id": "f1-4", "title": "Script de importação do acervo do WordPress para o novo banco", "phase": "Fase 2 · Migração e Backup", "status": "concluido", "note": "Em 23/09/2026, 7.577 matérias foram importadas no Supabase Free com HTML sanitizado e resumos gerados; 8 originais sem título ficaram como rascunho. Nenhuma mídia foi importada. Banco com cerca de 84 MB de 500 MB após o índice de busca. Pendentes: revisão das 31 editorias legadas, classificação dos tipos, mídia no R2 e delta do WordPress antes do go-live.", "week": 3, "position": 19}, {"source_id": "f2-8", "title": "Tags de anúncio DCM instaladas (SECOM · Saresp e Alfabetiza)", "phase": "Fase 2 · Migração e Backup", "status": "concluido", "note": "Concluído — as 4 tags recebidas da Baila/Maisis (970×250, 728×90, 300×250, 300×600) foram instaladas nos slots correspondentes do protótipo. Referência completa em ANUNCIOS-DCM.md. Pendente: confirmar com a agência se o flight de abril/2026 ainda vale ou se vem campanha nova; o slot 320×50 do rodapé mobile ficou sem tag.", "week": 4, "position": 20}, {"source_id": "f3-1", "title": "Cadastro de leitores", "phase": "Fase 3 · Editorial e Backend", "status": "concluido", "note": "Concluído no portal Next.js com Supabase Auth, perfil criado por trigger e RLS. Confirmação por e-mail aguarda URL autorizada e provedor de envio na etapa de migração.", "week": 5, "position": 21}, {"source_id": "f3-2", "title": "Área personalizada do leitor", "phase": "Fase 3 · Editorial e Backend", "status": "concluido", "note": "Concluído: login, recuperação de senha, preferências, matérias salvas, exportação e exclusão de dados. Fluxo de e-mail será validado após ativação externa.", "week": 6, "position": 22}, {"source_id": "f3-3", "title": "Newsletter", "phase": "Fase 3 · Editorial e Backend", "status": "concluido", "note": "Backend Resend concluído: consentimento confirmado, descadastro, fila idempotente, disparo manual e teto global de 90 e-mails/dia e 2.800/mês. Sem chave/domínio; zero envios.", "week": 6, "position": 23}, {"source_id": "f3-4", "title": "Avisos de notícia no navegador (push)", "phase": "Fase 3 · Editorial e Backend", "status": "concluido", "note": "Backend web push concluído: inscrição, cancelamento, service worker e disparo manual protegido. Ativação das chaves VAPID fica na migração; zero envios.", "week": 7, "position": 24}, {"source_id": "f3-5", "title": "Base técnica para assinatura futura", "phase": "Fase 3 · Editorial e Backend", "status": "concluido", "note": "Base técnica concluída: perfil do leitor com plano, status e data de assinatura; RLS impede que o próprio leitor altere esses campos. Cobrança e oferta comercial futuras não fazem parte desta etapa.", "week": 7, "position": 25}, {"source_id": "f4-1", "title": "SEO técnico e Google Notícias", "phase": "Fase 4 · Go-live", "status": "concluido", "note": "Implementado no Next.js: canonicals, metadados, NewsArticle, robots, sitemap completo, sitemap de notícias (48 horas) e RSS. Indexação depende do deploy e da virada de DNS.", "week": 7, "position": 26}, {"source_id": "f4-2", "title": "Virada de DNS", "phase": "Fase 4 · Go-live", "status": "a_fazer", "note": "Trocar o domínio para o novo portal após os testes finais.", "week": 8, "position": 27}, {"source_id": "f4-3", "title": "WordPress aposentado", "phase": "Fase 4 · Go-live", "status": "a_fazer", "note": "Desativar o site antigo depois que o novo portal estiver estável.", "week": 8, "position": 28}, {"source_id": "f4-4", "title": "Início dos 60 dias de suporte pós-entrega", "phase": "Fase 4 · Go-live", "status": "a_fazer", "note": "A contagem começa na entrega da estrutura.", "week": 9, "position": 29}]}'::jsonb; task jsonb; details jsonb := '{}'::jsonb;
begin
  select id into aid from public.agencies where slug='maisis';
  if aid is null then
    insert into public.agencies(name,slug,logo_url) values('Maisis Publicidade','maisis','/agencies/maisis/logo.png') returning id into aid;
  elsif not exists(select 1 from public.agencies where id=aid and name='Maisis Publicidade' and active) then raise exception 'Agency identity/status mismatch'; end if;
  select id into cid from public.clients where slug='gazeta-bragantina';
  if cid is null then
    if exists(select 1 from public.clients where name ilike '%gazeta%') then raise exception 'Review existing Gazeta client'; end if;
    insert into public.clients(name,slug) values('Gazeta Bragantina','gazeta-bragantina') returning id into cid;
  elsif not exists(select 1 from public.clients where id=cid and name='Gazeta Bragantina') then raise exception 'Client identity mismatch'; end if;
  if (select count(*) from public.projects where client_id=cid and name='Portal Gazeta Bragantina')>1 then raise exception 'Duplicate project'; end if;
  select id into pid from public.projects where client_id=cid and name='Portal Gazeta Bragantina';
  if pid is null then
    insert into public.projects(client_id,name,lead_status,project_status,modules)
    values(cid,'Portal Gazeta Bragantina','EM_PRODUCAO','EM_REVISAO_CLIENTE','{"como_funciona":"ativo","prototipo":"ativo","etapas":"ativo","editor":"bloqueado","versoes":"bloqueado","marca":"bloqueado"}') returning id into pid;
  else
    update public.projects set project_status='EM_REVISAO_CLIENTE',modules=modules || '{"como_funciona":"ativo","prototipo":"ativo","etapas":"ativo","editor":"bloqueado"}' where id=pid;
  end if;
  if exists(select 1 from public.agency_projects where project_id=pid and agency_id<>aid) then raise exception 'Project already assigned to another agency'; end if;
  insert into public.agency_projects(agency_id,project_id) values(aid,pid) on conflict(project_id) do nothing;
  for task in select value from jsonb_array_elements(payload->'tasks') loop
    tid := null;
    select k.id into tid from public.kanban_items k where k.project_id=pid and k.title=task->>'title';
    if tid is null then
      insert into public.kanban_items(project_id,title,phase,status,position)
      values(pid,task->>'title',task->>'phase',(task->>'status')::public.kanban_status,(task->>'position')::integer) returning id into tid;
    else
      update public.kanban_items set phase=task->>'phase',status=(task->>'status')::public.kanban_status,position=(task->>'position')::integer where id=tid;
    end if;
    details := details || jsonb_build_object(tid::text,jsonb_build_object('source_id',task->>'source_id','note',task->>'note','week',task->'week'));
  end loop;
  insert into public.roadmaps(project_id,stack,costs,next_steps,"references",tiers,prototype_url,published_at)
  values(pid,payload->'roadmap'->'stack',payload->'roadmap'->'costs',(payload->'roadmap'->'next_steps') || jsonb_build_object('task_details',details),payload->'roadmap'->'references','{}',payload->'roadmap'->>'prototype_url',now())
  on conflict(project_id) do update set stack=excluded.stack,costs=excluded.costs,next_steps=excluded.next_steps,"references"=excluded."references",prototype_url=excluded.prototype_url,published_at=coalesce(roadmaps.published_at,excluded.published_at);
end $onboard$;
commit;
select c.id client_id,p.id project_id,a.id agency_id,c.name,p.project_status,p.modules,r.prototype_url,
(select count(*) from public.kanban_items where project_id=p.id) tasks,
(select count(*) from public.kanban_items where project_id=p.id and status='concluido') completed,
(select count(*) from public.memberships where client_id=c.id) client_memberships
from public.clients c join public.projects p on p.client_id=c.id join public.agency_projects ap on ap.project_id=p.id join public.agencies a on a.id=ap.agency_id join public.roadmaps r on r.project_id=p.id where c.slug='gazeta-bragantina';